// Prepare data and craft AI Prompt grounded in BookLeaf policies
const payload = $json.body || $json;

const authorId = payload.author_id || 'N/A';
const authorName = payload.author_name || 'Esteemed Author';
const authorEmail = payload.author_email || '';
const authorCity = payload.author_city || '';
const totalEarned = Number(payload.total_earned || 0);
const totalPaid = Number(payload.total_paid || 0);
const totalPending = Number(payload.total_pending || 0);
const books = payload.books || [];

// Determine payout cycle explanation based on BookLeaf 45-day window policy
let payoutPolicyText = '';
if (totalPending > 0) {
  payoutPolicyText = `BookLeaf calculates and processes royalties on a quarterly cycle. Under our standard policy, all pending royalties for the current quarterly cycle will be credited directly to your registered bank account within the standard 45-day window following the quarter end.`;
} else {
  payoutPolicyText = `All royalties for your published titles are fully settled and up to date. Thank you for your continued partnership!`;
}

// Format books summary for prompt
let booksText = '';
if (Array.isArray(books) && books.length > 0) {
  booksText = books.map(b => {
    if (b.status && b.status.includes('In Production')) {
      return `- ${b.title}: Currently in production (${b.status}). Sales and royalty tracking will begin once live.`;
    }
    return `- ${b.title} (ISBN: ${b.isbn || 'N/A'}): ${b.total_copies_sold || 0} copies sold. Earned: ₹${b.total_royalty_earned || 0}, Paid: ₹${b.royalty_paid || 0}, Pending: ₹${b.royalty_pending || 0}. Last payout: ${b.last_royalty_payout_date || 'N/A'}.`;
  }).join('\n');
} else if (payload.books_summary) {
  booksText = payload.books_summary;
} else {
  booksText = 'All active titles registered with BookLeaf Publishing.';
}

const systemPrompt = `You are the Author Royalty Communications Specialist at BookLeaf Publishing.
Your task is to write a warm, professional, human-readable royalty summary email to the author.

Guidelines & Knowledge Base Policies:
1. Personalised greeting using the author's name.
2. Clear summary of their published books, copies sold, and earnings.
3. Clear financial breakdown: Total Earned, Total Paid, and Total Pending in INR (₹).
4. If there is a pending balance, explain the payout schedule (quarterly cycle + 45-day processing window).
5. If pending balance is 0, give an appreciative positive acknowledgement.
6. If any book is in production (e.g., cover design or typesetting), provide a brief encouraging status update.
7. Closing must be warm, inspiring, and professional, signed off by "The BookLeaf Publishing Author Success Team".
8. Output ONLY the email text with subject line. Do not include markdown meta-commentary.`;

const userPrompt = `Author Name: ${authorName}
City: ${authorCity}
Email: ${authorEmail}
Total Lifetime Earned: ₹${totalEarned}
Total Paid: ₹${totalPaid}
Total Pending: ₹${totalPending}

Books Details:
${booksText}

Policy Context:
${payoutPolicyText}`;

return {
  author_id: authorId,
  author_name: authorName,
  author_email: authorEmail,
  total_earned: totalEarned,
  total_paid: totalPaid,
  total_pending: totalPending,
  system_prompt: systemPrompt,
  user_prompt: userPrompt,
  raw_payload: payload
};

// Format output or handle fallback if AI API failed
const pre = $('3. Data Pre-Processor & Policy Engine').first().json;
const aiResponse = $input.first().json;

let generatedEmail = '';
let status = 'Sent';
let errorMessage = null;

if (aiResponse && aiResponse.candidates && aiResponse.candidates[0] && aiResponse.candidates[0].content && aiResponse.candidates[0].content.parts[0]) {
  generatedEmail = aiResponse.candidates[0].content.parts[0].text;
} else if (aiResponse && aiResponse.error) {
  status = 'Failed';
  errorMessage = aiResponse.error.message || 'AI API returned an error';
  // Provide graceful fallback email template
  generatedEmail = `Subject: BookLeaf Publishing — Royalty Account Statement for ${pre.author_name}\n\nDear ${pre.author_name},\n\nHere is your official royalty summary across your registered titles with BookLeaf Publishing:\n- Total Royalty Earned: ₹${pre.total_earned}\n- Royalty Paid: ₹${pre.total_paid}\n- Royalty Pending: ₹${pre.total_pending}\n\n${pre.total_pending > 0 ? 'Your pending royalties are being processed within our standard quarterly 45-day window.' : 'All your royalties are fully settled.'}\n\nWarm regards,\nThe BookLeaf Publishing Team`;
} else {
  // Default fallback
  status = 'Sent';
  generatedEmail = `Subject: BookLeaf Publishing — Royalty Statement for ${pre.author_name}\n\nDear ${pre.author_name},\n\nWe are pleased to share your latest royalty summary statement:\n- Lifetime Royalties Earned: ₹${pre.total_earned}\n- Settled Royalties: ₹${pre.total_paid}\n- Current Pending Balance: ₹${pre.total_pending}\n\n${pre.total_pending > 0 ? 'Pending disbursements are scheduled under our quarterly 45-day cycle.' : 'All titles are fully settled.'}\n\nWarm regards,\nBookLeaf Publishing Author Success Team`;
}

return {
  status: status,
  author_id: pre.author_id,
  author_name: pre.author_name,
  author_email: pre.author_email,
  email_content: generatedEmail,
  error_message: errorMessage,
  sent_at: new Date().toISOString()
};

